export class AudioController {
  private audioContext: AudioContext | null = null;
  private analyser: AnalyserNode | null = null;
  private source: AudioNode | null = null;
  private buffer: AudioBuffer | null = null;
  private gainNode: GainNode | null = null;

  constructor() {
    // Initialize lazily
  }

  async init() {
    if (!this.audioContext) {
      this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      this.analyser = this.audioContext.createAnalyser();
      this.analyser.fftSize = 4096; 
      this.analyser.smoothingTimeConstant = 0.8;
      this.gainNode = this.audioContext.createGain();
      this.gainNode.connect(this.audioContext.destination);
    }
    if (this.audioContext.state === 'suspended') {
      await this.audioContext.resume();
    }
  }

  async loadFile(file: File): Promise<void> {
    await this.init();
    if (!this.audioContext) return;

    // Disconnect old mic/source if exists
    if (this.source) {
         this.source.disconnect();
         this.source = null;
    }

    const arrayBuffer = await file.arrayBuffer();
    this.buffer = await this.audioContext.decodeAudioData(arrayBuffer);
  }

  // NEW: Microphone Input
  async startMicrophone(): Promise<void> {
      await this.init();
      if (!this.audioContext || !this.analyser) return;

      if (this.source) {
          try { (this.source as any).stop?.(); } catch(e){}
          this.source.disconnect();
      }

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      this.source = this.audioContext.createMediaStreamSource(stream);
      this.source.connect(this.analyser);
      // NOTE: Mic is NOT connected to destination to prevent nasty feedback loops
  }

  play(onEnded?: () => void) {
    if (!this.audioContext || !this.buffer || !this.analyser || !this.gainNode) return;

    if (this.source) {
      try {
        (this.source as AudioBufferSourceNode).stop();
      } catch (e) {}
      this.source.disconnect();
    }

    const source = this.audioContext.createBufferSource();
    source.buffer = this.buffer;
    source.loop = false; 

    if (onEnded) {
        source.onended = onEnded;
    }

    source.connect(this.analyser);
    this.analyser.connect(this.gainNode);
    source.start(0);
    this.source = source;
  }

  stop() {
    if (this.source) {
      try {
        (this.source as AudioBufferSourceNode).stop();
      } catch (e) {}
      // Don't nullify source immediately for Mic usage, but for File playback it's okay. 
      // Actually, stop() implies stopping playback.
    }
  }

  getAnalyser(): AnalyserNode | null {
    return this.analyser;
  }

  getSampleRate(): number {
      return this.audioContext ? this.audioContext.sampleRate : 44100;
  }
}

const NOTE_STRINGS = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];

function getNoteFromFrequency(frequency: number): string {
    if (!isFinite(frequency) || frequency === 0) return "--";
    const noteNum = 12 * (Math.log(frequency / 440) / Math.log(2)) + 69;
    const note = Math.round(noteNum);
    const octave = Math.floor(note / 12) - 1;
    const noteIndex = note % 12;
    if (noteIndex < 0 || octave < 0 || octave > 8) return "--";
    return `${NOTE_STRINGS[noteIndex]}${octave}`;
}

export const analyzeFrequencies = (analyser: AnalyserNode, frequencyArray: Uint8Array, timeDomainArray: Uint8Array, sampleRate: number) => {
  analyser.getByteFrequencyData(frequencyArray);
  analyser.getByteTimeDomainData(timeDomainArray);

  const bufferLength = analyser.frequencyBinCount;

  const bassRange = Math.floor(bufferLength * 0.05); 
  const midRange = Math.floor(bufferLength * 0.25);  

  let bassSum = 0;
  let midSum = 0;
  let trebleSum = 0;
  let maxVal = -1;
  let maxIndex = -1;

  for (let i = 0; i < bufferLength; i++) {
    const value = frequencyArray[i];

    if (i > 5 && value > maxVal) {
        maxVal = value;
        maxIndex = i;
    }

    if (i < bassRange) {
      bassSum += value;
    } else if (i < midRange) {
      midSum += value;
    } else {
      trebleSum += value;
    }
  }

  const bass = bassSum / bassRange;
  const mid = midSum / (midRange - bassRange);
  const treble = trebleSum / (bufferLength - midRange);
  const average = (bass + mid + treble) / 3;

  const nyquist = sampleRate / 2;
  const dominantFrequency = maxIndex !== -1 ? (maxIndex / bufferLength) * nyquist : 0;
  const note = maxVal > 100 ? getNoteFromFrequency(dominantFrequency) : "--"; 

  let mood = "Neutral";
  if (bass > mid * 1.5) mood = "Deep / Powerful";
  if (mid > bass && mid > treble) mood = "Warm / Vocal";
  if (treble > mid * 1.2) mood = "Ethereal / Bright";
  if (average > 180) mood = "Intense / Aggressive";

  return { bass, mid, treble, average, frequencyArray, timeDomainArray, dominantFrequency, note, mood };
};

