import React, { useState, useRef, Suspense } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Stars } from '@react-three/drei';
import { EffectComposer, Vignette, Bloom } from '@react-three/postprocessing';
import * as THREE from 'three';
import { CloudPoints } from './components/CloudPoints';
import { Overlay } from './components/Overlay';
import { AudioController, analyzeFrequencies } from './services/audioService';
import { LogEntry, SystemMode, VisualShape, VisualEffect } from './types';

// Data Logger Component
const DataLogger = ({ isPlaying, analyzer, setExperimentLog }: any) => {
    const lastLogTime = useRef(0);
    const dataArray = useRef(new Uint8Array(0));
    const timeArray = useRef(new Uint8Array(0));
    useFrame((state) => {
        if (!isPlaying || !analyzer) return;
        if (state.clock.elapsedTime - lastLogTime.current > 1.0) {
            lastLogTime.current = state.clock.elapsedTime;
            if (dataArray.current.length !== analyzer.frequencyBinCount) {
                dataArray.current = new Uint8Array(analyzer.frequencyBinCount);
                timeArray.current = new Uint8Array(analyzer.frequencyBinCount);
            }
            const analysis = analyzeFrequencies(analyzer, dataArray.current, timeArray.current, analyzer.context.sampleRate);
            setExperimentLog((prev: any) => [...prev, {
                timestampFormatted: `${Math.floor(state.clock.elapsedTime / 60)}:${Math.floor(state.clock.elapsedTime % 60).toString().padStart(2, '0')}`,
                elapsedTime: state.clock.elapsedTime,
                note: analysis.note || "--",
                frequencyHz: analysis.dominantFrequency || 0,
                amplitude: Math.max(analysis.bass, analysis.mid, analysis.treble) / 255.0,
                physicsMode: "LOGGING",
                bassLevel: analysis.bass, midLevel: analysis.mid, trebleLevel: analysis.treble
            }]);
        }
    });
    return null;
}

const App: React.FC = () => {
  const [audioController] = useState(() => new AudioController());
  const [analyzer, setAnalyzer] = useState<AnalyserNode | null>(null);
  const [hasAudio, setHasAudio] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [loading, setLoading] = useState(false);
  const [systemMode] = useState<SystemMode>('EDU_LAB');
  const [experimentLog, setExperimentLog] = useState<LogEntry[]>([]);

  // Visual State
  const [currentShape, setCurrentShape] = useState<VisualShape>('ORB');
  const [currentEffect, setCurrentEffect] = useState<VisualEffect>('FLOW');

  const handleFileUpload = async (file: File) => {
    setLoading(true); audioController.stop(); setIsPlaying(false);
    try {
      await audioController.loadFile(file);
      setAnalyzer(audioController.getAnalyser());
      setHasAudio(true);
      audioController.play(() => setIsPlaying(false));
      setIsPlaying(true);
    } catch (e) { console.error(e); } finally { setLoading(false); }
  };

  // Microphone Support
  const handleMicrophone = async () => {
      setLoading(true); audioController.stop(); setIsPlaying(false);
      try {
          await audioController.startMicrophone();
          setAnalyzer(audioController.getAnalyser());
          setHasAudio(true);
          setIsPlaying(true);
      } catch (e) { 
          console.error(e); 
          alert("Microphone access denied or not available. Please allow permissions.");
      } finally { setLoading(false); }
  };

  const togglePlay = () => {
    if (isPlaying) audioController.stop(); 
    else audioController.play(() => setIsPlaying(false));
    setIsPlaying(!isPlaying);
  };

  return (
    <div className="w-full h-screen bg-black relative overflow-hidden">
      <Overlay 
        onFileUpload={handleFileUpload} hasAudio={hasAudio} isPlaying={isPlaying} togglePlay={togglePlay}
        onDownloadStudent={() => {}} onDownloadResearch={() => {}} hasLog={false}
        systemMode={systemMode} setSystemMode={() => {}} analyzer={analyzer}
        onMicrophone={handleMicrophone}
        currentShape={currentShape} setShape={setCurrentShape}
        currentEffect={currentEffect} setEffect={setCurrentEffect}
      />

      {loading && <div className="absolute inset-0 flex items-center justify-center z-20 bg-black/90 text-cyan-500 font-mono text-xl animate-pulse">INITIALIZING SYSTEM...</div>}

      <Canvas dpr={[1, 1.5]} camera={{ position: [0, 0, 45], fov: 60 }} gl={{ antialias: false, toneMapping: THREE.ACESFilmicToneMapping, toneMappingExposure: 1.2 }}>
        <color attach="background" args={['#050505']} />
        <Stars radius={100} depth={50} count={2000} factor={4} saturation={0} fade speed={1} />

        <CloudPoints 
            analyzer={analyzer} 
            isPlaying={isPlaying} 
            systemMode={systemMode}
            shape={currentShape}
            effect={currentEffect}
        />

        <DataLogger isPlaying={isPlaying} analyzer={analyzer} setExperimentLog={setExperimentLog} />

        <OrbitControls enableZoom={true} autoRotate={true} autoRotateSpeed={0.5} rotateSpeed={0.5} maxDistance={150} minDistance={5} />

        <Suspense fallback={null}>
            <EffectComposer disableNormalPass multisampling={0}>
                <Vignette eskil={false} offset={0.1} darkness={1.1} />
                <Bloom luminanceThreshold={0.1} luminanceSmoothing={0.9} intensity={2.0} radius={0.6} />
            </EffectComposer>
        </Suspense>
      </Canvas>
    </div>
  );
};

export default App;

