import React, { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { ParticleSystemProps, AudioAnalysis, VisualShape } from '../types';
import { analyzeFrequencies } from '../services/audioService';

export const CloudPoints: React.FC<ParticleSystemProps> = ({ analyzer, isPlaying, shape, effect }) => {
  const meshRef = useRef<THREE.Points>(null);

  // 12,000 particles is a good balance for density and performance
  const PARTICLE_COUNT = 12000;

  const frequencyArray = useMemo(() => new Uint8Array(analyzer ? analyzer.frequencyBinCount : 0), [analyzer]);
  const timeDomainArray = useMemo(() => new Uint8Array(analyzer ? analyzer.frequencyBinCount : 0), [analyzer]);

  // Initialize particles with random data just to hold memory
  const particles = useMemo(() => {
    const positions = new Float32Array(PARTICLE_COUNT * 3);
    const colors = new Float32Array(PARTICLE_COUNT * 3);
    const indices = new Float32Array(PARTICLE_COUNT);

    const c = new THREE.Color();
    c.setHSL(0.5, 1.0, 0.5);

    for (let i = 0; i < PARTICLE_COUNT; i++) {
      indices[i] = i;
      positions[i * 3] = (Math.random() - 0.5) * 50;
      positions[i * 3 + 1] = (Math.random() - 0.5) * 50;
      positions[i * 3 + 2] = (Math.random() - 0.5) * 50;

      colors[i * 3] = c.r;
      colors[i * 3 + 1] = c.g;
      colors[i * 3 + 2] = c.b;
    }

    return { positions, colors, indices };
  }, []);

  // Helper to lerp values
  const lerp = (start: number, end: number, t: number) => {
      // Guard against NaN values to prevent geometry corruption
      if (isNaN(start)) start = 0;
      if (isNaN(end)) end = 0;
      return start * (1 - t) + end * t;
  };

  useFrame((state) => {
    if (!meshRef.current) return;

    const time = state.clock.getElapsedTime();
    const positions = meshRef.current.geometry.attributes.position.array as Float32Array;
    const colors = meshRef.current.geometry.attributes.color.array as Float32Array;

    let audioData: AudioAnalysis = { 
        bass: 0, mid: 0, treble: 0, average: 0, 
        frequencyArray, timeDomainArray, dominantFrequency: 0
    };

    if (analyzer && isPlaying) {
      audioData = analyzeFrequencies(analyzer, frequencyArray, timeDomainArray, analyzer.context.sampleRate);
    }

    // Audio Factors (Normalized 0.0 - 1.0)
    // Ensure these are numbers, fallback to 0
    const f_bass = (audioData.bass || 0) / 255.0;
    const f_mid = (audioData.mid || 0) / 255.0;
    const f_treble = (audioData.treble || 0) / 255.0;
    const f_avg = (audioData.average || 0) / 255.0;

    // Palette: Electric Blue / Cyan
    const colorBase = new THREE.Color("#001133"); // Deep Blue
    const colorHigh = new THREE.Color("#00f0ff"); // Electric Cyan
    const colorPeak = new THREE.Color("#ffffff"); // White Hot

    // Lerp factor for smooth movement (inertia)
    const lerpFactor = 0.1; 

    const freqArrayLen = audioData.frequencyArray.length;

    for (let i = 0; i < PARTICLE_COUNT; i++) {
      const i3 = i * 3;

      // Calculate Target Position based on Shape
      let tx = 0, ty = 0, tz = 0;
      const idxNorm = i / PARTICLE_COUNT; // 0 to 1

      // --- TOPOLOGY MATH ---
      if (shape === 'ORB') {
        // Fibonacci Sphere Distribution
        const goldenRatio = (1 + Math.sqrt(5)) / 2;
        const theta = 2 * Math.PI * i / goldenRatio;
        // Clamp value for acos to avoid NaN due to floating point precision
        const phiInput = 1 - 2 * (i + 0.5) / PARTICLE_COUNT;
        const phi = Math.acos(Math.max(-1, Math.min(1, phiInput)));
        const r = 20;

        tx = r * Math.sin(phi) * Math.cos(theta);
        ty = r * Math.cos(phi);
        tz = r * Math.sin(phi) * Math.sin(theta);

      } else if (shape === 'TORUS') {
        // Toroidal coordinates
        const u = idxNorm * Math.PI * 2 * 20; // 20 loops
        const v = idxNorm * Math.PI * 2;
        const R = 20; // Main radius
        const r = 6;  // Tube radius

        tx = (R + r * Math.cos(v)) * Math.cos(u);
        tz = (R + r * Math.cos(v)) * Math.sin(u);
        ty = r * Math.sin(v);

      } else if (shape === 'PLANE') {
        // Grid Plane
        const size = 60;
        const side = Math.sqrt(PARTICLE_COUNT);
        const x = (i % side) / side; // 0 to 1
        const z = Math.floor(i / side) / side; // 0 to 1

        tx = (x - 0.5) * size;
        ty = 0;
        tz = (z - 0.5) * size;

      } else if (shape === 'DNA') {
        // Double Helix
        const h = 60;
        const turns = 5;
        const y = (idxNorm - 0.5) * h;
        const angle = idxNorm * Math.PI * 2 * turns;
        const r = 10;

        // Split into two strands
        const offset = i % 2 === 0 ? 0 : Math.PI;

        tx = Math.cos(angle + offset) * r;
        ty = y;
        tz = Math.sin(angle + offset) * r;
      }

      // --- PHYSICS / EFFECTS ---
      let dx = 0, dy = 0, dz = 0;

      // Map frequency to this particle safely
      let freqVal = 0;
      if (freqArrayLen > 0) {
          const freqIndex = Math.floor(idxNorm * (freqArrayLen * 0.5));
          const val = audioData.frequencyArray[freqIndex];
          if (val !== undefined) {
             freqVal = val / 255.0;
          }
      }

      if (effect === 'FLOW') {
          // Gentle sine wave flow
          const wave = Math.sin(idxNorm * 20 + time * 2) * f_mid * 2;
          const noise = Math.sin(tx * 0.1 + time) * f_bass * 1;

          dx = tx * (freqVal * 0.5); // Expand out
          dy = wave + noise;
          dz = tz * (freqVal * 0.5);

      } else if (effect === 'PULSE') {
          // Beat heavy expansion
          const beat = f_bass * f_bass * f_bass * 10; // Sharp beat

          dx = tx * 0.01 * beat;
          dy = ty * 0.01 * beat;
          dz = tz * 0.01 * beat;

      } else if (effect === 'NOISE') {
          // Chaos
          dx = Math.sin(ty * 0.2 + time * 5) * f_treble * 2;
          dy = Math.cos(tx * 0.2 + time * 5) * f_treble * 2;
          dz = Math.sin(idxNorm * 100 + time) * f_mid * 2;

      } else if (effect === 'VORTEX') {
          // Rotational pull is handled by autoRotate, here we do vertical lift
          dy = Math.sin(idxNorm * Math.PI * 4 + time * 3) * (f_bass * 5);
      }

      // Apply target with lerp for smoothness
      // Note: We use the array itself as 'current' position
      positions[i3] = lerp(positions[i3], tx + dx, lerpFactor);
      positions[i3 + 1] = lerp(positions[i3 + 1], ty + dy, lerpFactor);
      positions[i3 + 2] = lerp(positions[i3 + 2], tz + dz, lerpFactor);

      // --- COLORING (Electric Blue Aesthetic) ---
      // Brighter if higher frequency or bass hit
      const brightness = 0.2 + freqVal * 0.8 + (f_bass * 0.3);

      const cFinal = colorBase.clone();
      // Lerp towards Cyan based on mids
      cFinal.lerp(colorHigh, freqVal + f_mid * 0.5);
      // Lerp towards White based on Treble/Peak
      if (brightness > 0.8) {
          cFinal.lerp(colorPeak, (brightness - 0.8) * 2);
      }

      colors[i3] = cFinal.r;
      colors[i3 + 1] = cFinal.g;
      colors[i3 + 2] = cFinal.b;
    }

    meshRef.current.geometry.attributes.position.needsUpdate = true;
    meshRef.current.geometry.attributes.color.needsUpdate = true;
  });

  return (
    <points ref={meshRef}>
      <bufferGeometry>
        <bufferAttribute
          attach="attributes-position"
          count={particles.positions.length / 3}
          array={particles.positions}
          itemSize={3}
        />
        <bufferAttribute
          attach="attributes-color"
          count={particles.colors.length / 3}
          array={particles.colors}
          itemSize={3}
        />
      </bufferGeometry>
      <pointsMaterial
        size={0.15} 
        vertexColors
        transparent
        opacity={0.9}
        blending={THREE.AdditiveBlending}
        depthWrite={false}
        sizeAttenuation={true}
      />
    </points>
  );
};

