import React from 'react';
import { SystemMode, UploadProps, VisualShape, VisualEffect } from '../types';
import { PhysicsPanel } from './PhysicsPanel';

interface OverlayProps extends UploadProps {
  hasAudio: boolean;
  isPlaying: boolean;
  togglePlay: () => void;
  onDownloadStudent: () => void; 
  onDownloadResearch: () => void;
  hasLog: boolean;
  systemMode: SystemMode;
  setSystemMode: (m: SystemMode) => void;
  analyzer: AnalyserNode | null; 
  onMicrophone?: () => void;

  // Visual Controls
  currentShape: VisualShape;
  setShape: (s: VisualShape) => void;
  currentEffect: VisualEffect;
  setEffect: (e: VisualEffect) => void;
}

export const Overlay: React.FC<OverlayProps> = ({ 
  onFileUpload, hasAudio, isPlaying, togglePlay, systemMode, analyzer, onMicrophone,
  currentShape, setShape, currentEffect, setEffect
}) => {
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) onFileUpload(e.target.files[0]);
  };

  const shapes: VisualShape[] = ['ORB', 'TORUS', 'PLANE', 'DNA'];
  const effects: VisualEffect[] = ['FLOW', 'PULSE', 'NOISE', 'VORTEX'];

  return (
    <div className="absolute inset-0 pointer-events-none z-10 flex flex-col justify-between text-white overflow-hidden font-rajdhani">

      {/* HEADER */}
      <header className="pointer-events-auto bg-black/80 backdrop-blur-md border-b border-cyan-900/30 w-full">
        <div className="max-w-7xl mx-auto p-2 md:p-3 flex flex-col md:flex-row items-center justify-between gap-2 md:gap-4">
            <div className="flex items-center gap-4">
                <h1 className="text-2xl font-bold tracking-widest text-cyan-500" style={{ textShadow: '0 0 10px rgba(6,182,212,0.5)' }}>
                    FLUX ENGINE
                </h1>
            </div>

            <div className="flex-1 flex justify-center w-full md:w-auto">
                 <PhysicsPanel analyzer={analyzer} isPlaying={isPlaying} systemMode={systemMode} />
            </div>

            <div className="flex items-center gap-2">
                <label className="cursor-pointer bg-cyan-900/20 hover:bg-cyan-900/40 border border-cyan-500/30 px-3 py-1.5 rounded flex items-center gap-2 transition-all">
                    <span className="text-[10px] font-bold text-cyan-300">LOAD AUDIO</span>
                    <input type="file" accept="audio/*" className="hidden" onChange={handleFileChange} />
                </label>
                {onMicrophone && (
                   <button onClick={onMicrophone} className="bg-red-900/20 hover:bg-red-900/40 border border-red-500/30 text-red-300 px-3 py-1.5 rounded text-[10px] font-bold transition-all">
                       MIC INPUT
                   </button>
                )}
                {hasAudio && (
                    <button onClick={togglePlay} className={`w-8 h-8 flex items-center justify-center rounded-full border transition-all ${isPlaying ? 'border-cyan-400 text-cyan-400 bg-cyan-900/30 shadow-[0_0_10px_rgba(6,182,212,0.3)]' : 'border-gray-600 text-gray-400'}`}>
                        {isPlaying ? '⏸' : '▶'}
                    </button>
                )}
            </div>
        </div>
      </header>

      {/* FOOTER CONTROLS */}
      <div className="pointer-events-auto bg-gradient-to-t from-black via-black/90 to-transparent pb-4 pt-8 px-4">
          <div className="max-w-3xl mx-auto flex flex-col md:flex-row items-center justify-center gap-6 md:gap-12">

              {/* SHAPE SELECTOR */}
              <div className="flex flex-col items-center gap-2">
                  <span className="text-[10px] text-cyan-500/70 tracking-[0.2em] font-bold">TOPOLOGY</span>
                  <div className="flex gap-1 bg-black/50 border border-cyan-900/30 rounded-lg p-1">
                      {shapes.map(shape => (
                          <button 
                            key={shape} 
                            onClick={() => setShape(shape)}
                            className={`px-3 py-1 text-[10px] font-bold rounded transition-all ${currentShape === shape ? 'bg-cyan-600 text-white shadow-[0_0_10px_rgba(6,182,212,0.5)]' : 'text-gray-400 hover:text-cyan-300 hover:bg-white/5'}`}
                          >
                              {shape}
                          </button>
                      ))}
                  </div>
              </div>

              {/* EFFECT SELECTOR */}
              <div className="flex flex-col items-center gap-2">
                  <span className="text-[10px] text-cyan-500/70 tracking-[0.2em] font-bold">PHYSICS</span>
                  <div className="flex gap-1 bg-black/50 border border-cyan-900/30 rounded-lg p-1">
                      {effects.map(effect => (
                          <button 
                            key={effect} 
                            onClick={() => setEffect(effect)}
                            className={`px-3 py-1 text-[10px] font-bold rounded transition-all ${currentEffect === effect ? 'bg-indigo-600 text-white shadow-[0_0_10px_rgba(79,70,229,0.5)]' : 'text-gray-400 hover:text-indigo-300 hover:bg-white/5'}`}
                          >
